// app/api/asteroids/route.js
// This file runs on the server, so the key never reaches the browser.
export async function GET() {
  const day = new Date().toISOString().slice(0, 10);
  const key = process.env.NASA_API_KEY;
  const url = `https://api.nasa.gov/neo/rest/v1/feed?start_date=${day}&end_date=${day}&api_key=${key}`;

  const reply = await fetch(url);
  if (!reply.ok) {
    return Response.json({ error: "NASA request failed" }, { status: 502 });
  }
  const data = await reply.json();

  return Response.json(data.near_earth_objects[day] ?? [], {
    // Let the host reuse this answer for an hour.
    headers: { "Cache-Control": "s-maxage=3600, stale-while-revalidate" },
  });
}

const XRAY = "https://services.swpc.noaa.gov/json/goes/primary/xrays-6-hour.json";
const KP = "https://services.swpc.noaa.gov/products/noaa-planetary-k-index.json";

// Turn raw flux (watts per square metre) into a class like "M2.4".
function flareClass(flux) {
  const classes = [["X", 1e-4], ["M", 1e-5], ["C", 1e-6], ["B", 1e-7], ["A", 1e-8]];
  for (const [letter, floor] of classes) {
    if (flux >= floor || letter === "A") return letter + (flux / floor).toFixed(1);
  }
}

async function getSolar() {
  const [xrays, kps] = await Promise.all(
    [XRAY, KP].map((url) => fetch(url).then((reply) => reply.json())),
  );
  const band = xrays.filter((r) => r.energy === "0.1-0.8nm"); // the flare band
  const latest = band[band.length - 1];
  return {
    flare: flareClass(latest.flux),
    kp: Number(kps[kps.length - 1].Kp), // storm level, 0 to 9
    time: latest.time_tag,
  };
}

