"use client";
import { useEffect, useState } from "react";

// Calls load() now, then again every few milliseconds.
export function usePolling(load, everyMs) {
  const [state, setState] = useState({ data: null, error: null, loading: true });

  useEffect(() => {
    let stopped = false;
    async function run() {
      try {
        const data = await load();
        if (!stopped) setState({ data, error: null, loading: false });
      } catch (error) {
        // Keep the last good data on screen and show the error beside it.
        if (!stopped) setState((old) => ({ ...old, error, loading: false }));
      }
    }
    run();
    const timer = setInterval(run, everyMs);
    return () => { stopped = true; clearInterval(timer); }; // panel left the page
  }, [load, everyMs]);

  return state;
}

"use client";
import { usePolling } from "./usePolling";

export default function SolarPanel() {
  // getSolar sits outside the component, so it is the same function every render.
  const { data, error, loading } = usePolling(getSolar, 60_000);

  if (loading) return <section>Loading solar data...</section>;
  if (!data) return <section>Solar data is unavailable right now.</section>;

  return (
    <section>
      <h2>Solar activity</h2>
      <p>Flare class: {data.flare}</p>
      <p>Storm level (Kp): {data.kp}</p>
      {error && <p className="warn">Could not refresh. Showing older data.</p>}
    </section>
  );
}

// asteroids: from getAsteroids(). solar: from getSolar().
function getAlerts(asteroids, solar) {
  const alerts = [];

  const close = asteroids.filter((a) => a.hazardous && a.moonDistances < 20);
  if (close.length) {
    alerts.push(`${close.length} flagged asteroid(s) within 20 Moon distances`);
  }
  if (solar.kp >= 5) {
    alerts.push(`Geomagnetic storm, Kp ${solar.kp}. Aurora may appear further from the poles`);
  }
  if (/^[MX]/.test(solar.flare)) {
    alerts.push(`Strong solar flare: ${solar.flare}`);
  }
  return alerts;
}

